#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    let pre_tail = pre.tail;
    let buffer_size = pre.buffer_size;
    let min_local_version = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);

    // Key facts:
    // 1. post.tail = new_tail, post.buffer_size = buffer_size (constant)
    // 2. post.contents = pre.contents - withdrawn where withdrawn = [pre_tail - buffer_size, new_tau - buffer_size)
    // 3. post.alive_bits = pre.alive_bits, post.local_versions = pre.local_versions
    // 4. From transition: pre.tail <= new_tau <= observed_head + buffer_size
    // 5. From pre.combiner_valid(AdvancingTail): observed_head <= pre.local_versions[n] for all n
    // 6. From pointer_ordering: pre.tail <= pre.local_versions[n] for all n, so pre.tail <= min_local_version
    // 7. From pointer_differences: pre.tail <= min_local_version + buffer_size
    // 8. From 4,5,6: new_tau <= pre.tail + buffer_size, so new_tau - buffer_size <= pre_tail
    // 9. withdrawn range = [pre_tau - buffer_size, new_tau - buffer_size)
    // 10. post range = [new_tau - buffer_size, new_tau)
    // 11. These are adjacent (withdrawn ends where post starts)

    // Part 1: inv_buffer_contents for post state
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) || i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==>
        #[trigger] post.contents.contains_key(i) by {
        // i in post.range = [new_tau - buffer_size, new_tau)
        // withdrawn = [pre_tau - buffer_size, new_tau - buffer_size)
        // Since i >= new_tau - buffer_size and withdrawn ends at new_tau - buffer_size (exclusive),
        // i is NOT in withdrawn range
        // So post.contents.contains_key(i) == pre.contents.contains_key(i)

        if i >= pre_tail {
            // i >= pre_tau
            // From pre.inv_buffer_contents: !pre.contents.contains_key(i) for i >= pre_tau
            assert(!pre.contents.contains_key(i)) by {
                // From pre.inv_buffer_contents invariant
            };
            assert(!post.contents.contains_key(i));

            // Need to show: !(alive_post(i) || i < min_local_post)
            // = !alive_post(i) && i >= min_local_post

            // From pointer_ordering: pre.tail <= pre.local_versions[n] for all n
            // So pre.tail <= min_local_version
            // Since i >= pre_tau, we have i >= min_local_version
            assert(i >= map_min_value(post.local_versions, (post.num_replicas - 1) as nat)) by {
                // From pointer_ordering
            };

            // From upcoming_bits_are_not_alive in pre state:
            // pre.tail <= i < min_local_version + buffer_size ==> !alive_pre(i)
            // We have i >= pre_tau and from transition: new_tau <= pre.tail + buffer_size
            // So i < new_tau <= pre_tau + buffer_size
            // So i < pre_tau + buffer_size <= min_local_version + buffer_size
            // So i < min_local_version + buffer_size
            assert(i < min_local_version + buffer_size);
            assert(!log_entry_is_alive(pre.alive_bits, i as int, buffer_size)) by {
                // From pre.upcoming_bits_are_not_alive
            };
            assert(!log_entry_is_alive(post.alive_bits, i as int, post.buffer_size));
        } else {
            // i < pre_tau and i >= new_tau - buffer_size
            // So new_tau - buffer_size <= i < pre_tau

            // From transition: new_tau >= pre_tau, so new_tau - buffer_size >= pre_tau - buffer_size
            // So i >= new_tau - buffer_size >= pre_tau - buffer_size
            // Therefore i in [pre_tau - buffer_size, pre_tau)
            assert(pre_tail - buffer_size <= i < pre_tail) by {
                // new_tau - buffer_size >= pre_tau - buffer_size because new_tau >= pre_tau
            };

            // From pre.inv_buffer_contents for this range:
            assert(pre.contents.contains_key(i) <==> log_entry_is_alive(pre.alive_bits, i as int, buffer_size) || i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)) by {
                // From pre.inv_buffer_contents
            };

            // Since post.contents = pre.contents (i not in withdrawn), post.alive = pre.alive, post.local_versions = pre.local_versions:
            assert(post.contents.contains_key(i) <==> log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) || i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat));
        }
    }

    // Part 2: forall |i: int| post.tail <= i ==> !post.contents.contains_key(i)
    assert forall |i: int| post.tail <= i implies !#[trigger] post.contents.contains_key(i) by {
        // i >= post.tail = new_tau >= pre_tau
        // From pre.inv_buffer_contents: !pre.contents.contains_key(i) for i >= pre_tau
        assert(!pre.contents.contains_key(i)) by {
            // From pre.inv_buffer_contents
        };

        // withdrawn = [pre_tau - buffer_size, new_tau - buffer_size)
        // For i >= new_tau: withdrawn ends at new_tau - buffer_size < new_tau <= i
        // So i NOT in withdrawn
        // Therefore post.contents.contains_key(i) = pre.contents.contains_key(i) = false
        assert(!post.contents.contains_key(i));
    }

    // Part 3: all_combiner_valid for post state
    // For node_id, combiner changed from AdvancingTail to Appending

    assert(post.combiner_valid(node_id, CombinerState::Appending { cur_idx: pre_tail, tail: new_tail }));

    // Check Appending conditions:
    assert(pre.local_versions.contains_key(node_id));
    assert(pre.local_versions[node_id] <= pre_tail);
    assert(pre_tail <= new_tail);
    assert(new_tau <= post.tail);
    assert(new_tau - buffer_size <= pre_tail);
    assert(pre_tail <= new_tau);

    assert forall |i: nat| pre_tail <= i < new_tail implies !log_entry_is_alive(post.alive_bits, i as int, post.buffer_size) by {
        // From transition: new_tau <= pre_tau + buffer_size
        // So i < new_tau <= pre_tau + buffer_size
        // From pointer_differences: pre_tau <= min_local_version + buffer_size
        // So i < min_local_version + buffer_size
        assert(i < min_local_version + buffer_size);
        assert(!log_entry_is_alive(pre.alive_bits, i as int, buffer_size)) by {
            // From pre.upcoming_bits_are_not_alive
        };
        assert(!log_entry_is_alive(post.alive_bits, i as int, post.buffer_size));
    };

    // For other nodes, combiner is unchanged
    assert forall |node_id2: NodeId| #[trigger] post.combiner.contains_key(node_id2) && node_id2 != node_id implies
        post.combiner_valid(node_id2, post.combiner[node_id2]) by {
        // combiner unchanged for node_id2
        assert(pre.combiner[node_id2] == post.combiner[node_id2]);
        // From pre.all_combiner_valid
        assert(pre.combiner_valid(node_id2, pre.combiner[node_id2]));
    };
}

