#[inductive(advance_tail_finish)]
fn advance_tail_finish_inductive(pre: Self, post: Self, node_id: NodeId, new_tail: nat) {
    // Key from transition: pre.tail <= new_tail <= observed_head + pre.buffer_size
    // And observed_head <= pre.local_versions[n] for all n (from prev.combiner_valid)
    // So observed_head <= min_local_version where min_local_version = map_min_value(pre.local_versions, ...)
    // Therefore new_tau <= min_local_version + pre.buffer_size
    // So new_tau - pre.buffer_size <= min_local_version

    // From pointer_ordering: pre.tail <= pre.local_versions[n] for all n
    // So pre.tail <= min_local_version

    // From pointer_differences: pre.tail <= pre.local_versions[n] + pre.buffer_size for all n
    // So pre.tail <= min_local_version + pre.buffer_size

    // From transition: new_tau <= observed_head + pre.buffer_size <= pre.tail + pre.buffer_size (since observed_head <= pre.tail)
    // So new_tau - pre.buffer_size <= pre_tail

    // post.tail = new_tau, post.buffer_size = pre.buffer_size (constant)
    // post.contents = pre.contents - withdrawn where withdrawn = [pre_tau - pre.buffer_size, new_tau - pre.buffer_size)
    // post.alive_bits = pre.alive_bits, post.local_versions = pre.local_versions

    let pre_tail = pre.tail;
    let buffer_size = pre.buffer_size;
    let min_local_version = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);

