            assert(!pre.contents.contains_key(i));
            // And withdrawn = [pre_tau - buffer_size, new_tau - buffer_size), so i >= pre_tau >= new_tau - buffer_size (from new_tau - buffer_size <= pre_tau)
            // So i NOT in withdrawn
