            // So i < min_local_version + buffer_size
            assert(i < min_local_version + buffer_size);
            assert(!log_entry_is_alive(pre.alive_bits, i as int, buffer_size));
            assert(!log_entry_is_alive(post.alive_bits, i as int, post.buffer_size));
        } else {
            // i < pre_tau and i >= new_tau - buffer_size
            // So new_tau - buffer_size <= i < pre_tau

