            // So i >= new_tau - buffer_size >= pre_tau - buffer_size
            // Therefore i in [pre_tau - buffer_size, pre_tau)
            assert(pre_tail - buffer_size <= i < pre_tau);

            // From pre.inv_buffer_contents for this range:
            assert(pre.contents.contains_key(i) <==> log_entry_is_alive(pre.alive_bits, i as int, buffer_size) || i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat));

            // withdrawn = [pre_tau - buffer_size, new_tau - buffer_size)
            // i < pre_tau and i >= new_tau - buffer_size
            // Since new_tau - buffer_size <= pre_tau (from new_tau <= pre_tau + buffer_size)
            // And i < pre_tau, we need to check if i >= new_tau - buffer_size
            // withdrawn range is [pre_tau - buffer_size, new_tau - buffer_size)
            // i >= new_tau - buffer_size, so i NOT in withdrawn (since withdrawn ends at new_tau - buffer_size, exclusive)
            // Therefore post.contents.contains_key(i) = pre.contents.contains_key(i)
            assert(post.contents.contains_key(i) == pre.contents.contains_key(i));

