    // = (new_tau - buffer_size) <= pre_tail <= new_tau
    // From transition: new_tau <= pre_tau + buffer_size, so new_tau - buffer_size <= pre_tau
    assert(new_tau - buffer_size <= pre_tail);
    assert(pre_tail <= new_tau);

